import { expect } from '@esm-bundle/chai';
// DOM nodes are compared as booleans (`a === b`): a failing chai assertion carrying DOM nodes hangs the runner.
// NO static import of the component: <td-dropzone> is defined LATE (dynamic import below), after the no-JS checks.

// v0.100.0 (ADR 0012, plan v0.100.0-batch C) — td_dropzone() / <td-dropzone> hydrate, contract `dropzone@1`, in Chromium,
// Firefox AND WebKit (group `engines`). The markup is EXACTLY what php/td.php prints for every case of
// test/ssr/dropzone.fixtures.json: test/ssr/fixtures/dropzone.html, generated by `node test/ssr/build-dropzone-fixture.mjs`
// and kept fresh by test/php/td-ssr-dropzone.test.js. Files are picked BEFORE the upgrade with a REAL FileList
// (DataTransfer → input.files).
const link = document.createElement('link');
link.rel = 'stylesheet';
link.href = '/td.css';
document.head.appendChild(link);
await new Promise((r) => { link.onload = r; link.onerror = r; });

const SPEC = await (await fetch('/test/ssr/dropzone.fixtures.json')).json();
const FIXTURE = await (await fetch('/test/ssr/fixtures/dropzone.html')).text();
const TPL = document.createElement('template');
TPL.innerHTML = FIXTURE;

const root = document.createElement('div');
root.innerHTML = FIXTURE;
document.body.appendChild(root);

const formOf = (id, scope = root) => scope.querySelector(`form[data-case="${id}"]`);
const hostOf = (id, scope = root) => scope.querySelector(`form[data-case="${id}"] > td-dropzone`);
// the refused-markup hosts use a SUBCLASS tag (defined in a second step): the focus can only sit on one input at the
// upgrade, and the valid and the refused path each need it
const mmHost = (id) => mismatch.querySelector(`form[data-case="${id}"] > td-dropzone-x`);
const hostHtml = (id) => TPL.content.querySelector(`form[data-case="${id}"] > td-dropzone`).outerHTML;
const inputOf = (host) => host.querySelector('input[type="file"]');
const TYPES = { pdf: 'application/pdf', png: 'image/png', svg: 'image/svg+xml' };
const pick = (input, ...names) => {
  const dt = new DataTransfer();
  for (const n of names) dt.items.add(new File([`content of ${n}`], n, { type: TYPES[n.split('.').pop()] || 'text/plain' }));
  input.files = dt.files;
  return [...input.files];
};

// Hand-written mismatches (must render, never adopt; the files picked in their ONE native input still arrive).
const base = hostHtml('e-multiple-hint');
const MM = {
  'mm-onclick': base.replace('<input ', '<input onclick="window.__pwned = 1" '),
  'mm-schema': base.replace('dropzone@1', 'dropzone@2'),
  'mm-tabindex': base.replace('<input ', '<input tabindex="-1" '),
  'mm-formaction': base.replace('<input ', '<input formaction="/evil" '),
  'mm-hidden-input': base.replace('</div></td-dropzone>', '</div><input type="hidden" name="docs[]" value="x"></td-dropzone>'),
  'mm-hint-text': base.replace('Tối đa 5 MB mỗi file', 'Tối đa 6 MB mỗi file'),
  'mm-icon-content': base.replace('aria-hidden="true"></span><p', 'aria-hidden="true"><b>x</b></span><p'),
  'mm-two-files': base.replace('<div class="td-dropzone__zone">', '<input type="file" class="td-dropzone__input" name="docs[]"><div class="td-dropzone__zone">'),
};
const mismatch = document.createElement('div');
const rename = (html, id) => html.replace(/td-docs-\d+/g, id).replace('<td-dropzone ', '<td-dropzone-x ').replace('</td-dropzone>', '</td-dropzone-x>');
mismatch.innerHTML = Object.entries(MM).map(([id, html]) => `<form data-case="${id}">${rename(html, id)}</form>`).join('');
document.body.appendChild(mismatch);

// --- before the module loads (no JS): the server input IS the field ---
const noJs = {};
{
  const f = formOf('e-multiple-hint');
  const input = inputOf(f.querySelector('td-dropzone'));
  const files = pick(input, 'one.pdf', 'two.pdf');
  noJs.fd = new FormData(f).getAll('docs[]').map((x) => x.name);
  const req = hostOf('e-label-required');
  const reqInput = inputOf(req);
  noJs.requiredBlocks = formOf('e-label-required').checkValidity() === false && reqInput.validity.valueMissing === true;
  const cs = getComputedStyle(reqInput);
  const rect = reqInput.getBoundingClientRect();
  noJs.visible = cs.opacity === '1' && cs.position === 'static' && rect.width > 40 && rect.height > 10;
  noJs.tabIndex = reqInput.tabIndex;
  noJs.hiddenAttrs = reqInput.hasAttribute('tabindex') || reqInput.hasAttribute('aria-hidden');
  noJs.browseDisplay = getComputedStyle(req.querySelector('.td-dropzone__browse')).display;
  reqInput.focus();
  noJs.focusable = document.activeElement === reqInput;
  const labelled = (reqInput.getAttribute('aria-labelledby') || '').split(/\s+/).filter(Boolean).map((i) => document.getElementById(i));
  noJs.name = labelled.map((n) => (n ? n.textContent.trim() : null));
  const described = (inputOf(hostOf('e-multiple-hint')).getAttribute('aria-describedby') || '').split(/\s+/).filter(Boolean).map((i) => document.getElementById(i));
  noJs.described = described.map((n) => (n ? n.textContent.trim() : null));
  noJs.files = files;
  noJs.noLabelName = inputOf(hostOf('e-basic')).getAttribute('aria-label');
  noJs.nativeRequired = formOf('n-full').checkValidity();
  noJs.nativeLabel = formOf('n-full').querySelector('label').textContent;
}
// valid markup: the user picked files in two adopted fields; one adopted field has the focus (the required one, empty)
const before = {};
for (const c of SPEC.cases) before[c.id] = inputOf(hostOf(c.id));
const picked = { 'e-multiple-hint': noJs.files, 'e-stacked': pick(before['e-stacked'], 'cover.png'), 'e-badges': pick(before['e-badges'], 'a.svg', 'b.pdf', 'c.png') };
const hadFocus = document.activeElement === before['e-label-required'];
// refused markup: files picked in each one's native input, the focus on one of them
const tampered = {};
const tamperedFiles = {};
for (const id of Object.keys(MM)) {
  tampered[id] = inputOf(mmHost(id));
  tamperedFiles[id] = pick(tampered[id], `${id}-1.pdf`, `${id}-2.pdf`);
}

// an upload hook set BEFORE the upgrade (pre-upgrade property): while it runs for an adopted file, the form holds ONE
// entry per file (the native input gave up `name` before the queue took the files; Codex v0.100.0 impl review)
const hookFd = [];
hostOf('e-multiple-hint').upload = () => {
  hookFd.push(new FormData(formOf('e-multiple-hint')).getAll('docs[]').length);
  return Promise.resolve();
};

const events = [];
for (const type of ['input', 'change', 'files-change']) {
  document.addEventListener(type, (e) => { if (e.target instanceof Element && e.target.closest('td-dropzone, td-dropzone-x')) events.push(type); }, true);
}
const frames = () => new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));

// step 1: the module defines <td-dropzone> — the valid hosts upgrade (the focus sits on the required one's input)
const { TdDropzone } = await import('./td-dropzone.js');
await frames();
const eventsAtUpgrade = events.length;
const afterFocus = { required: document.activeElement === hostOf('e-label-required').querySelector('.td-dropzone__browse') };
// step 2: the refused hosts upgrade (the focus sits on a tampered one's input)
tampered['mm-onclick'].focus();
const mmFocused = document.activeElement === tampered['mm-onclick'];
customElements.define('td-dropzone-x', class extends TdDropzone {});
await frames();
const eventsAtRefused = events.length;
afterFocus.tampered = document.activeElement === mmHost('mm-onclick').querySelector('.td-dropzone__browse');

const names = (host) => host.files.map((f) => f.name);
const rows = (host) => [...host.querySelectorAll('.td-dropzone__item .td-dropzone__name')].map((n) => n.textContent);
const fdNames = (host) => new FormData(host.closest('form')).getAll(host.getAttribute('name')).map((f) => f.name);

describe('td-dropzone SSR (dropzone@1) — no JS', () => {
  it('the server file input is the field: visible, in the tab order, named, labelled and described', () => {
    expect(noJs.visible, 'native input shown').to.equal(true);
    expect(noJs.tabIndex).to.equal(0);
    expect(noJs.hiddenAttrs, 'no tabindex / aria-hidden before the upgrade').to.equal(false);
    expect(noJs.focusable).to.equal(true);
    expect(noJs.name).to.deep.equal(['Tệp đính kèm *']);
    expect(noJs.described).to.deep.equal(['Định dạng: .pdf, image/* · Tối đa 5 MB mỗi file · Tối đa 3 file', 'Tối đa 3 file.']);
    expect(noJs.noLabelName).to.equal('Chọn file');
  });

  it('the JS-only "choose" button is not displayed', () => {
    expect(noJs.browseDisplay).to.equal('none');
  });

  it('native FormData holds the picked files under `name`; `required` blocks the submit', () => {
    expect(noJs.fd).to.deep.equal(['one.pdf', 'two.pdf']);
    expect(noJs.requiredBlocks).to.equal(true);
  });

  it('the native (no element) field has its label and a required file input, and the module leaves it alone', () => {
    expect(noJs.nativeRequired).to.equal(false);
    expect(noJs.nativeLabel).to.equal('Tài liệu *');
    expect(formOf('n-full').querySelector('td-dropzone')).to.equal(null);
    expect(formOf('n-full').querySelector('input').type).to.equal('file');
  });
});

describe('td-dropzone SSR — adopted in place', () => {
  for (const c of SPEC.cases) {
    it(`${c.id}: same input node, marker consumed, no-JS attributes swapped for the JS render's, one empty queue`, () => {
      const host = hostOf(c.id);
      const input = inputOf(host);
      const want = c.expect;
      expect(input === before[c.id], 'input node kept').to.equal(true);
      expect(host.hasAttribute('data-td-ssr')).to.equal(false);
      expect(host instanceof TdDropzone).to.equal(true);
      for (const a of ['name', 'required', 'aria-labelledby', 'aria-label', 'aria-describedby']) expect(input.hasAttribute(a), `no-JS ${a} removed`).to.equal(false);
      expect(input.getAttribute('tabindex')).to.equal('-1');
      expect(input.getAttribute('aria-hidden')).to.equal('true');
      expect(input.classList.contains('td-dropzone__input')).to.equal(true);
      expect(input.multiple).to.equal(!!want.multiple);
      expect(input.disabled).to.equal(!!want.disabled);
      expect(host.required).to.equal(!!want.required);
      if (want.hostId) expect(host.id).to.equal(want.hostId);
      if (want.label) expect(host.querySelector('.td-dropzone__label').childNodes[0].textContent).to.equal(want.label);
      const hint = host.querySelector('.td-dropzone__hint');
      expect(hint.hidden).to.equal(want.hint === '');
      expect(hint.textContent).to.equal(want.hint);
      if (want.helper) expect(host.querySelector('.td-field__note').textContent).to.equal(want.helper);
      expect(getComputedStyle(host.querySelector('.td-dropzone__browse')).display).to.not.equal('none');
      expect(host.querySelector('.td-dropzone__icon svg') !== null, 'icon drawn on bind').to.equal(true);
      if (!picked[c.id] && !want.disabled) expect(fdNames(host)).to.deep.equal([]);
    });
  }

  it('the files picked before the upgrade are in the queue (same File objects), rows rendered, ONE FormData entry per file', () => {
    for (const id of Object.keys(picked)) {
      const host = hostOf(id);
      const files = picked[id];
      expect(host.files.length).to.equal(files.length);
      expect(host.files.every((f, i) => f === files[i]), `${id}: same File objects`).to.equal(true);
      expect(rows(host)).to.deep.equal(files.map((f) => f.name));
      expect(fdNames(host)).to.deep.equal(files.map((f) => f.name));
      expect(inputOf(host).value, 'the native input is emptied (the queue owns the files)').to.equal('');
      expect(host.querySelector('.td-dropzone__list').hidden).to.equal(false);
    }
  });

  it('an early upload hook runs for the adopted files and never sees the native input still named', () => {
    expect(hookFd.length).to.equal(noJs.files.length);
    expect(hookFd.every((n) => n <= noJs.files.length), `entries seen: ${hookFd}`).to.equal(true);
  });

  it('hydrate fired no input / change / files-change; the files/rows came in silently', () => {
    expect(eventsAtUpgrade).to.equal(0);
  });

  it('the input had the focus → the "choose" button has it now (the input is hidden from the tab order)', () => {
    expect(hadFocus).to.equal(true);
    expect(afterFocus.required).to.equal(true);
  });

  it('ElementInternals owns validity: required + empty → valueMissing; a file clears it', () => {
    const host = hostOf('e-label-required');
    expect(host.validity.valueMissing).to.equal(true);
    expect(host.checkValidity()).to.equal(false);
    host.addFiles([new File(['x'], 'x.txt', { type: 'text/plain' })]);
    expect(host.validity.valid).to.equal(true);
    expect(fdNames(host)).to.deep.equal(['x.txt']);
    host.clear();
    expect(host.validity.valueMissing).to.equal(true);
  });

  it('form.reset() clears the list and the form value', () => {
    const host = hostOf('e-multiple-hint');
    host.closest('form').reset();
    expect(host.files.length).to.equal(0);
    expect(fdNames(host)).to.deep.equal([]);
    expect(rows(host)).to.deep.equal([]);
  });

  it('the component keeps working after the adoption: a new pick through the input adds a file and fires files-change once', () => {
    const host = hostOf('e-basic');
    const input = inputOf(host);
    let n = 0;
    host.addEventListener('files-change', () => { n++; });
    pick(input, 'later.txt');
    input.dispatchEvent(new Event('change', { bubbles: true }));
    expect(n).to.equal(1);
    expect(names(host)).to.deep.equal(['later.txt']);
    expect(fdNames(host)).to.deep.equal(['later.txt']);
  });

  it('a disabled field is not submitted', () => {
    expect(fdNames(hostOf('e-disabled'))).to.deep.equal([]);
    expect(inputOf(hostOf('e-disabled')).disabled).to.equal(true);
  });
});

describe('td-dropzone SSR — refused markup renders safely, the picked files and the focus survive', () => {
  for (const id of Object.keys(MM)) {
    it(`${id}: re-rendered, nothing foreign survives, files in the queue, one FormData entry per file`, () => {
      const host = mmHost(id);
      const files = tamperedFiles[id];
      expect(host.hasAttribute('data-td-ssr')).to.equal(false);
      expect(host instanceof TdDropzone).to.equal(true);
      expect(host.querySelectorAll('input').length).to.equal(1);
      expect(inputOf(host).type).to.equal('file');
      expect(inputOf(host).hasAttribute('name'), 'name left to the host').to.equal(false);
      expect(inputOf(host).getAttribute('tabindex')).to.equal('-1');
      expect(!!host.querySelector('[onclick], [formaction], b, input[type="hidden"]')).to.equal(false);
      expect(window.__pwned).to.equal(undefined);
      if (id === 'mm-two-files') {
        expect(host.files.length, 'two candidate inputs → no state taken').to.equal(0);
        return;
      }
      expect(host.files.length).to.equal(files.length);
      expect(host.files.every((f, i) => f === files[i]), 'same File objects').to.equal(true);
      expect(rows(host)).to.deep.equal(files.map((f) => f.name));
      expect(fdNames(host)).to.deep.equal(files.map((f) => f.name));
    });
  }

  it('the same native input node is moved into the safe render (attributes replaced by the render\'s)', () => {
    const host = mmHost('mm-onclick');
    expect(inputOf(host) === tampered['mm-onclick']).to.equal(true);
    expect(inputOf(host).hasAttribute('onclick')).to.equal(false);
    expect(inputOf(host).value).to.equal('');
  });

  it('the focus (on the input) is kept: it moves to the "choose" button of the safe render', () => {
    expect(mmFocused).to.equal(true);
    expect(afterFocus.tampered).to.equal(true);
  });

  it('no input / change / files-change from the refused path either', () => {
    expect(eventsAtRefused).to.equal(0);
  });
});
